python3 -c 'import subprocess,difflib; base="7f6b5d4b567c06ce9a4764b94352366ef008c22b"; files=subprocess.check_output(["git","diff","--name-only",base+"..HEAD","--",":(glob).planning/**/*-PLAN.md"],text=True).splitlines(); mechanical=[]
for f in files:
 p=subprocess.run(["git","show",base+":"+f],text=True,capture_output=True); old=p.stdout; new=open(f).read(); normalized=old.replace("~","~")
 if normalized==new: mechanical.append(f)
 else: print("".join(difflib.unified_diff(normalized.splitlines(True),new.splitlines(True),fromfile=f+" (base, home normalized)",tofile=f)))
print("EXACT HOME-PATH SUBSTITUTION ONLY:",len(mechanical),"of",len(files),"plans"); print("\n".join(mechanical))'

python3 -c 'import subprocess,collections; d=subprocess.check_output(["git","diff","--unified=0","7f6b5d4b567c06ce9a4764b94352366ef008c22b..HEAD","--",":(glob).planning/**/*-PLAN.md"],text=True); groups=collections.defaultdict(list); f=""
for line in d.splitlines():
 if line.startswith("+++ b/"): f=line[6:]
 elif line.startswith("+") and "~" in line and "86-pilot-reference-record" not in f: groups[line[1:]].append(f)
for line,files in groups.items(): print(str(len(files))+" files: "+line)'

